patch.diff:
--- a/zoo/contracts/ballot-leaky.compact
+++ b/zoo/contracts/ballot-leaky.compact
@@ -27,11 +27,13 @@
   voters.insert(disclose(voterTag(voterKey())));
 }

+witness ballotsNonce(): Bytes<32>; // fresh random bytes per call, kept to open the commitment
+
 export circuit vote(): [] {
   const tag = disclose(voterTag(voterKey()));
   assert(voters.member(tag), "not a registered voter");
   assert(!ballots.member(tag), "already voted");
   const c = choice();
   assert(c < 4, "there are four candidates");
-  ballots.insert(tag, disclose(choiceHash(c)));
+  ballots.insert(tag, disclose(persistentCommit<Bytes<32>>(choiceHash(c), ballotsNonce())));
 }

