patch.diff:
--- a/zoo/contracts/vault-leaky.compact
+++ b/zoo/contracts/vault-leaky.compact
@@ -16,10 +16,10 @@

 export circuit claim(): [] {
   assert(owner == default<Bytes<32>>, "already claimed");
-  owner = disclose(secretKey());
+  owner = disclose(persistentHash<Vector<2, Bytes<32>>>([pad(32, "vault-leaky:owner"), secretKey()]));
 }

 export circuit withdraw(): [] {
-  assert(owner == disclose(secretKey()), "not the owner");
+  assert(owner == disclose(persistentHash<Vector<2, Bytes<32>>>([pad(32, "vault-leaky:owner"), secretKey()])), "not the owner");
   withdrawals.increment(1);
 }

